const escapeRegExp=(s:string)=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
/** Replace literal text in named text slots across assets. Frozen assets and over-length results are reported, never partially written. */
export function bulkReplaceBrandText(d:DesignDocument,options:{assetIds:readonly string[];slotName?:string;find:string;replace:string;matchCase?:boolean}):BrandBulkResult{if(!options.assetIds.length)throw Error('Choose at least one asset.');if(!options.find)throw Error('Enter the text to find.');if(typeof options.replace!=='string'||controls.test(options.replace))throw Error('Enter valid replacement text.');const pattern=new RegExp(escapeRegExp(options.find),options.matchCase?'g':'gi'),result:BrandBulkResult={changed:0,occurrences:0,skipped:[]};for(const id of options.assetIds){const asset=brandAsset(d,id);if(!brandSlotsEditable(asset.status)){result.skipped.push({assetId:id,reason:BRAND_STATUS_LABEL[asset.status]});continue;}let touched=false;for(const slot of asset.slots){if(slot.kind!=='text'||options.slotName&&slot.name!==options.slotName)continue;const n=brandSlotNode(d,slot),matches=n.text.match(pattern)?.length??0;if(!matches)continue;const value=n.text.replace(pattern,()=>options.replace);try{writeText(n,slot,value);}catch(e){result.skipped.push({assetId:id,reason:(e as Error).message});continue;}touched=true;result.occurrences+=matches;}if(touched)result.changed++;}return result;}
/** Write the same text into one slot across assets. */
export function bulkSetBrandText(d:DesignDocument,options:{assetIds:readonly string[];slotName:string;value:string}):BrandBulkResult{if(!options.assetIds.length)throw Error('Choose at least one asset.');const result:BrandBulkResult={changed:0,occurrences:0,skipped:[]};for(const id of options.assetIds){const asset=brandAsset(d,id),slot=asset.slots.find(s=>s.kind==='text'&&s.name===options.slotName);if(!slot){result.skipped.push({assetId:id,reason:'No matching slot'});continue;}if(!brandSlotsEditable(asset.status)){result.skipped.push({assetId:id,reason:BRAND_STATUS_LABEL[asset.status]});continue;}writeText(brandSlotNode(d,slot),slot,options.value);result.changed++;result.occurrences++;}return result;}
/** One image fills every target; several images map in asset order and must match the editable target count exactly. */
export function bulkReplaceBrandImage(d:DesignDocument,options:{assetIds:readonly string[];slotName:string;images:readonly BrandImage[]}):BrandBulkResult{if(!options.assetIds.length)throw Error('Choose at least one asset.');if(!options.images.length)throw Error('Choose at least one image.');const result:BrandBulkResult={changed:0,occurrences:0,skipped:[]},targets:BrandSlot[]=[];for(const id of options.assetIds){const asset=brandAsset(d,id),slot=asset.slots.find(s=>s.kind==='image'&&s.name===options.slotName);if(!slot)result.skipped.push({assetId:id,reason:'No matching slot'});else if(!brandSlotsEditable(asset.status))result.skipped.push({assetId:id,reason:BRAND_STATUS_LABEL[asset.status]});else targets.push(slot);}if(options.images.length>1&&options.images.length!==targets.length)throw Error(`Choose one image or exactly ${targets.length} ${targets.length===1?'image':'images'} for the editable assets.`);targets.forEach((slot,i)=>{writeImage(brandSlotNode(d,slot),options.images[options.images.length===1?0:i]);result.changed++;result.occurrences++;});return result;}
export interface BrandSearchHit {kind:'asset'|'template'|'color'|'font';id:string;label:string;detail:string;}
export function brandSearchText(d:Pick<DesignDocument,'pages'|'brand'>){if(!d.brand)return '';const parts:string[]=[d.brand.kit.name,...d.brand.templates.map(t=>t.name),...d.brand.kit.colors.flatMap(c=>[c.name,c.value]),...d.brand.kit.fonts],page=d.pages.find(p=>p.id===d.brand!.assetPageId);if(page){const byId=new Map(page.nodes.map(n=>[n.id,n]));for(const a of d.brand.assets){parts.push(byId.get(a.frameId)?.name??'');for(const s of a.slots)if(s.kind==='text')parts.push(byId.get(s.nodeId)?.text??'');}}return parts.join('\n').toLocaleLowerCase();}
/** All tokens must match. Searches names, template, category, status, size, batch and text slot content; never image bytes. */
export function searchBrand(d:Pick<DesignDocument,'pages'|'brand'>,query:string,filter:{status?:BrandAssetStatus;templateId?:string;batchId?:string;campaign?:string}={}):BrandSearchHit[]{const brand=brandOf(d),tokens=query.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean),page=brandPage(d,'asset'),byId=new Map(page.nodes.map(n=>[n.id,n])),templates=new Map(brand.templates.map(t=>[t.id,t])),batches=new Map(brand.batches.map(b=>[b.id,b])),hit=(value:string)=>tokens.every(token=>value.includes(token)),out:BrandSearchHit[]=[];for(const a of brand.assets){if(filter.status&&a.status!==filter.status||filter.templateId&&a.templateId!==filter.templateId||filter.batchId&&a.batchId!==filter.batchId||filter.campaign&&a.campaign!==filter.campaign)continue;const name=byId.get(a.frameId)?.name??'',template=templates.get(a.templateId),size=a.sizeId?brandSize(a.sizeId):undefined,slots=a.slots.flatMap(s=>s.kind==='text'?[s.name,byId.get(s.nodeId)?.text??'']:[s.name]);if(hit([name,a.campaign,template?.name,template?.category,BRAND_STATUS_LABEL[a.status],size?.name,a.batchId?batches.get(a.batchId)?.name:'',...slots].join('\n').toLocaleLowerCase()))out.push({kind:'asset',id:a.id,label:name,detail:[template?.name,size?.name,BRAND_STATUS_LABEL[a.status]].filter(Boolean).join(' · ')});}if(!filter.status&&!filter.batchId&&!filter.templateId&&!filter.campaign&&tokens.length){for(const t of brand.templates)if(hit([t.name,t.category,...t.slots.map(s=>s.name)].join('\n').toLocaleLowerCase()))out.push({kind:'template',id:t.id,label:t.name,detail:`${t.category} · ${t.status==='published'?'Published':'Draft'}`});for(const c of brand.kit.colors)if(hit((c.name+' '+c.value).toLocaleLowerCase()))out.push({kind:'color',id:c.value,label:c.name,detail:c.value});for(const f of brand.kit.fonts)if(hit(f.toLocaleLowerCase()))out.push({kind:'font',id:f,label:f,detail:'Brand font'});}return out;}
export interface BrandExportEntry {assetId:string;frameId:string;fileBase:string;}
/** Stable, unique, path-free export names. Approved-only is an explicit filter, not an implied review. */
export function brandExportPlan(d:Pick<DesignDocument,'pages'|'brand'>,assetIds:readonly string[],options:{approvedOnly?:boolean}={}):BrandExportEntry[]{const page=brandPage(d,'asset'),byId=new Map(page.nodes.map(n=>[n.id,n])),used=new Set<string>(),entries:BrandExportEntry[]=[];for(const id of assetIds){const asset=brandAsset(d,id);if(options.approvedOnly&&asset.status!=='approved')continue;const frame=byId.get(asset.frameId);if(!frame)throw Error('An asset frame is missing.');const stem=(frame.name.replace(/[\u0000-\u001f\u007f-\u009f/\\:*?"<>|]+/g,' ').replace(/\s+/g,' ').replace(/^[.\s]+/,'').trim()||'Asset').slice(0,160)+` ${Math.round(frame.width)}x${Math.round(frame.height)}`;let fileBase=stem,n=2;while(used.has(fileBase.toLocaleLowerCase()))fileBase=`${stem} ${n++}`;used.add(fileBase.toLocaleLowerCase());entries.push({assetId:id,frameId:asset.frameId,fileBase});}return entries;}
export interface BrandVersionSlot {slotId:string;name:string;kind:BrandSlotKind;current:string|undefined;saved:string|undefined;changed:boolean;}
/** Compare one asset against a saved version of the same file. Values stay local to the caller. */
export function compareBrandAssetVersion(current:Pick<DesignDocument,'pages'|'brand'>,saved:Pick<DesignDocument,'pages'|'brand'>,assetId:string){const now=current.brand?.assets.find(a=>a.id===assetId),then=saved.brand?.assets.find(a=>a.id===assetId);if(!now)throw Error('This asset no longer exists.');if(!then)return {present:false,status:undefined,slots:[] as BrandVersionSlot[],changed:false};const slots=now.slots.map(slot=>{const old=then.slots.find(s=>s.id===slot.id),currentValue=brandSlotValue(current,slot);let savedValue:string|undefined;try{savedValue=old?brandSlotValue(saved,old):undefined;}catch{savedValue=undefined;}return {slotId:slot.id,name:slot.name,kind:slot.kind,current:currentValue,saved:savedValue,changed:currentValue!==savedValue};});return {present:true,status:then.status,slots,changed:slots.some(s=>s.changed)};}
/** Restore one asset's slot content from a saved version as a normal, undoable edit. Locked styling is untouched. */
export function restoreBrandAssetVersion(d:DesignDocument,saved:Pick<DesignDocument,'pages'|'brand'>,assetId:string){const asset=editableAsset(d,assetId),then=saved.brand?.assets.find(a=>a.id===assetId);if(!then)throw Error('This asset is not in the saved version.');let changed=0;for(const slot of asset.slots){const old=then.slots.find(s=>s.id===slot.id);if(!old)continue;const n=brandSlotNode(d,slot),value=brandSlotValue(saved,old);if(value===brandSlotValue(d,slot))continue;if(slot.kind==='text')writeText(n,slot,value);else{const source=brandSlotNode(saved,old),paint=source.paints?.find(p=>p.type==='image');writeImage(n,{image:value,width:paint?.imageWidth??n.width,height:paint?.imageHeight??n.height});}changed++;}return changed;}
